{"command": "python3 -c "
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    data = json.load(f)

# Extract request bodies
paths = data['paths']
for path, methods in paths.items():
    for method, details in methods.items():
        if 'requestBody' in details:
            schema = details['requestBody']['content']['application/json']['schema']
            props = list(schema.get('properties', {}).keys())
            reqs = schema.get('required', [])
            print(f'{details[\"operationId\"]}: required={reqs}, properties={props}')
        else:
            print(f'{details[\"operationId\"]}: NO request body')
"", "summary": "Extract request body schemas for all endpoints"}

