package auth

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"github.com/lab-sample-pickup-and-delivery/backend/internal/models"
	"golang.org/x/crypto/bcrypt"
)

var jwtSecret []byte

func init() {
	secret := os.Getenv("JWT_SECRET")
	if secret == "" {
		secret = "lab-sample-pickup-delivery-dev-secret-key-change-in-prod"
	}
	jwtSecret = []byte(secret)
}

func HashPassword(password string) (string, error) {
	bytes, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	return string(bytes), err
}

func CheckPassword(password, hash string) error {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(password))
}

type Claims struct {
	UserID         string   `json:"userId"`
	Username       string   `json:"username"`
	Roles          []string `json:"roles"`
	SelectedRole   string   `json:"selectedRole"`
	jwt.RegisteredClaims
}

func GenerateToken(userID, username string, roles []string, selectedRole string) (string, error) {
	claims := Claims{
		UserID:       userID,
		Username:     username,
		Roles:        roles,
		SelectedRole: selectedRole,
		RegisteredClaims: jwt.RegisteredClaims{
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(24 * time.Hour)),
			IssuedAt:  jwt.NewNumericDate(time.Now()),
		},
	}

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	return token.SignedString(jwtSecret)
}

func ValidateToken(tokenStr string) (*Claims, error) {
	token, err := jwt.ParseWithClaims(tokenStr, &Claims{}, func(token *jwt.Token) (interface{}, error) {
		if _, ok := token.Method.(*jwt.SigningMethodHMAC); !ok {
			return nil, fmt.Errorf("unexpected signing method")
		}
		return jwtSecret, nil
	})
	if err != nil {
		return nil, err
	}

	claims, ok := token.Claims.(*Claims)
	if !ok || !token.Valid {
		return nil, fmt.Errorf("invalid token")
	}

	return claims, nil
}

func GenerateID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b[:4]) + "-" +
		hex.EncodeToString(b[4:6]) + "-" +
		hex.EncodeToString(b[6:8]) + "-" +
		hex.EncodeToString(b[8:10]) + "-" +
		hex.EncodeToString(b[10:])
}

func HasRole(claims *Claims, role models.Role) bool {
	for _, r := range claims.Roles {
		if r == string(role) || r == string(models.RoleAdministrator) {
			return true
		}
	}
	return false
}

func RequireRole(claims *Claims, roles ...models.Role) bool {
	for _, rr := range claims.Roles {
		if rr == string(models.RoleAdministrator) {
			return true
		}
		for _, role := range roles {
			if rr == string(role) {
				return true
			}
		}
	}
	return false
}

