	var offeredTo string
	err := db.DB.QueryRow(`SELECT offered_to FROM assignments WHERE assignment_id=$1`, req.AssignmentID).Scan(&offeredTo)
	if err == sql.ErrNoRows {
		writeError(w, 404, "not_found", "Assignment not found")
		return
	}
	if offeredTo != userID {
		writeError(w, 403, "ineligible_worker", "Not offered to you")
