	db.DB.Exec(`UPDATE assignments SET status='declined', declined_by=$1, updated_at=NOW() WHERE assignment_id=$2`, newDeclined, req.AssignmentID)

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"assignmentId": req.AssignmentID,
			"status":       "declined",
		},
	})
