// POST /api/update-assignment-progress
func UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	if !hasRole(r, "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator") {
		writeError(w, 403, "forbidden", "Not authorized")
		return
	}

	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	userID := currentUserID(r)

	// Verify assignment ownership
	var workerID string
	err := db.DB.QueryRow(`SELECT worker_id FROM assignments WHERE assignment_id=$1`, req.AssignmentID).Scan(&workerID)
	if err == sql.ErrNoRows {
		writeError(w, 404, "not_found", "Assignment not found")
		return
	}
	if workerID != userID {
		writeError(w, 403, "ineligible_worker", "Not your assignment")
		return
	}

	_, err = db.DB.Exec(`UPDATE assignments SET status=$1, updated_at=NOW() WHERE assignment_id=$2`, req.Status, req.AssignmentID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update")
		return
	}

	if req.Status == "completed" {
		db.DB.Exec(`UPDATE journey_legs SET status='completed', completed_at=$1 WHERE assignment_id=$2`, req.OccurredAt, req.AssignmentID)
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"assignmentId": req.AssignmentID,
			"status":       req.Status,
		},
	})
}

// POST /api/initiate-handoff
func InitiateHandoff(w http.ResponseWriter, r *http.Request) {
	if !hasRole(r, "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator") {
		writeError(w, 403, "forbidden", "Not authorized")
		return
	}

	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	// Verify sender holds the sample
	var holderID string
	db.DB.QueryRow(`SELECT current_holder_id FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&holderID)
	if holderID != currentUserID(r) {
		writeError(w, 403, "forbidden", "You do not hold this sample")
