// POST /api/list-role-work
func ListRoleWork(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	role := req.Role
	if role == "" {
		role = selectedRole(r)
	}

	userID := currentUserID(r)

	roleWork := models.RoleWork{
		Pending:    []models.RoleWorkItem{},
		InProgress: []models.RoleWorkItem{},
		Completed:  []models.RoleWorkItem{},
	}

	switch role {
	case "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator":
		// Get assignments
		rows, err := db.DB.Query(`
			SELECT a.assignment_id, a.sample_id, a.status, a.kind, a.from_location_id, a.to_location_id, COALESCE(j.delivery_deadline::text, '')
			FROM assignments a
			LEFT JOIN journeys j ON a.journey_id = j.journey_id
			WHERE a.worker_id = $1 OR (a.offered_to = $1 AND a.status = 'offered')
			ORDER BY a.created_at DESC
			LIMIT 100`, userID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var aid, sid, status, kind, fromLoc, toLoc, deadline string
				rows.Scan(&aid, &sid, &status, &kind, &fromLoc, &toLoc, &deadline)

				item := createWorkItem(aid, sid, status, kind, fromLoc, toLoc, deadline)
				switch {
				case status == "offered" || status == "pending":
					roleWork.Pending = append(roleWork.Pending, item)
				case status == "accepted" || status == "in_progress":
					roleWork.InProgress = append(roleWork.InProgress, item)
				case status == "completed":
					roleWork.Completed = append(roleWork.Completed, item)
				}
			}
		}

	case "requester":
		// Get request-based samples
		rows, err := db.DB.Query(`
			SELECT s.sample_id, s.status, s.delivery_deadline::text
			FROM samples s
			JOIN collection_requests cr ON s.request_id = cr.request_id
			WHERE cr.requester_id = $1
			ORDER BY s.created_at DESC
			LIMIT 100`, userID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var sid, status, deadline string
				rows.Scan(&sid, &status, &deadline)
				item := models.SampleWorkItem{
					Kind:         "sample",
					AssignmentID: "",
					SampleID:     sid,
					Status:       status,
					Deadline:     deadline,
					History:      []models.TimelineEntry{},
				}
				switch {
				case status == "requested" || status == "planned":
					roleWork.Pending = append(roleWork.Pending, item)
				case status == "collected" || status == "in_transit":
					roleWork.InProgress = append(roleWork.InProgress, item)
				case status == "received" || status == "completed":
					roleWork.Completed = append(roleWork.Completed, item)
				}
			}
		}

	case "dispatcher", "administrator":
		rows, err := db.DB.Query(`SELECT sample_id, status, delivery_deadline::text FROM samples ORDER BY created_at DESC LIMIT 100`)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var sid, status, deadline string
				rows.Scan(&sid, &status, &deadline)
				item := models.SampleWorkItem{
					Kind:         "sample",
					AssignmentID: "",
					SampleID:     sid,
					Status:       status,
					Deadline:     deadline,
					History:      []models.TimelineEntry{},
				}
				switch {
				case status == "requested" || status == "planned" || status == "offered":
					roleWork.Pending = append(roleWork.Pending, item)
				case status == "collected" || status == "in_transit" || status == "accepted":
					roleWork.InProgress = append(roleWork.InProgress, item)
				case status == "received" || status == "completed":
					roleWork.Completed = append(roleWork.Completed, item)
				}
			}
		}
	}

	writeJSON(w, 200, map[string]any{"data": roleWork})
}

func createWorkItem(aid, sid, status, kind, fromLoc, toLoc, deadline string) models.RoleWorkItem {
	item := models.SampleWorkItem{
		Kind:         kind,
		AssignmentID: aid,
		SampleID:     sid,
		Status:       status,
		Deadline:     deadline,
		History:      []models.TimelineEntry{},
	}
	if fromLoc != "" {
		item.Destination = nil
	}
	return item
}

// POST /api/accept-assignment
func AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	userID := currentUserID(r)

	// Check assignment state
	var offeredTo, status string
	var workerID sql.NullString
	err := db.DB.QueryRow(`SELECT offered_to, status, worker_id FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
		Scan(&offeredTo, &status, &workerID)
	if err == sql.ErrNoRows {
		writeError(w, 404, "not_found", "Assignment not found")
		return
	}
	if err != nil {
		writeError(w, 500, "internal_error", "Database error")
		return
	}

	if status == "accepted" || status == "in_progress" || status == "completed" {
		if workerID.Valid && workerID.String == userID {
			writeJSON(w, 201, map[string]any{
				"data": map[string]any{
					"assignmentId": req.AssignmentID,
					"workerId":     userID,
					"status":       "accepted",
				},
			})
			return
		}
		writeError(w, 409, "assignment_taken", "Assignment already taken")
		return
	}

	if offeredTo != userID {
		writeError(w, 403, "ineligible_worker", "This assignment was not offered to you")
		return
	}

	if status != "offered" {
		writeError(w, 409, "offer_not_available", "Assignment no longer available")
		return
	}

	_, err = db.DB.Exec(`
		UPDATE assignments SET status='accepted', worker_id=$1, updated_at=NOW()
		WHERE assignment_id=$2 AND status='offered'`,
		userID, req.AssignmentID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to accept assignment")
		return
	}

	// Also update the leg
	db.DB.Exec(`UPDATE journey_legs SET worker_id=$1, status='accepted' WHERE assignment_id=$2`, userID, req.AssignmentID)

	auditLog(userID, selectedRole(r), "accept_assignment", "assignment", req.AssignmentID, true, "{}", "")

	writeJSON(w, 201, map[string]any{
		"data": map[string]any{
			"assignmentId": req.AssignmentID,
			"workerId":     userID,
			"status":       "accepted",
		},
	})
}

