// POST /api/search-audit-trail
func SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator") {
		writeError(w, 403, "forbidden", "Must be dispatcher or admin")
		return
	}

	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}

	orderClause := "timestamp DESC"
	if req.Order == "oldest_first" {
		orderClause = "timestamp ASC"
	}

	// Build query with filters
	conditions := []string{"1=1"}
	args := []any{}
	argN := 1

	if req.ActorID != "" {
		conditions = append(conditions, fmt.Sprintf("actor_id=$%d", argN))
		args = append(args, req.ActorID)
		argN++
	}
	if req.EntityType != "" {
		conditions = append(conditions, fmt.Sprintf("entity_type=$%d", argN))
		args = append(args, req.EntityType)
		argN++
	}
	if req.EntityID != "" {
		conditions = append(conditions, fmt.Sprintf("entity_id=$%d", argN))
		args = append(args, req.EntityID)
		argN++
	}
	if req.Action != "" {
		conditions = append(conditions, fmt.Sprintf("action=$%d", argN))
		args = append(args, req.Action)
		argN++
	}
	if req.Role != "" {
		conditions = append(conditions, fmt.Sprintf("role=$%d", argN))
		args = append(args, req.Role)
		argN++
	}
	if req.Success != nil {
		conditions = append(conditions, fmt.Sprintf("success=$%d", argN))
		args = append(args, *req.Success)
		argN++
	}
	if req.FromTime != "" {
		conditions = append(conditions, fmt.Sprintf("timestamp >= $%d", argN))
		args = append(args, req.FromTime)
		argN++
	}
	if req.ToTime != "" {
		conditions = append(conditions, fmt.Sprintf("timestamp <= $%d", argN))
		args = append(args, req.ToTime)
		argN++
	}

	whereClause := strings.Join(conditions, " AND ")

	// Count total
	var total int
	countQuery := fmt.Sprintf("SELECT COUNT(*) FROM audit_log WHERE %s", whereClause)
	db.DB.QueryRow(countQuery, args...).Scan(&total)

	// Fetch entries
	query := fmt.Sprintf(`
		SELECT audit_id, COALESCE(actor_id::text,''), role, action, entity_type, entity_id, success, changes::text, details, timestamp::text
		FROM audit_log WHERE %s ORDER BY %s LIMIT $%d OFFSET $%d`,
		whereClause, orderClause, argN, argN+1)
	args = append(args, req.Limit, req.Offset)

	rows, err := db.DB.Query(query, args...)
	if err != nil {
		writeError(w, 500, "internal_error", "Query failed")
		return
	}
	defer rows.Close()

	entries := []models.AuditEntry{}
	for rows.Next() {
		var e models.AuditEntry
		var changesStr string
		rows.Scan(&e.AuditID, &e.ActorID, &e.Role, &e.Action, &e.EntityType, &e.EntityID, &e.Success, &changesStr, &e.Details, &e.Timestamp)
		json.Unmarshal([]byte(changesStr), &e.Changes)
		entries = append(entries, e)
	}

	hasMore := total > req.Offset+req.Limit
	nextOffset := 0
	if hasMore {
		nextOffset = req.Offset + req.Limit
	}

	result := models.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     req.Offset,
		Limit:      req.Limit,
		Order:      req.Order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}

	writeJSON(w, 200, map[string]any{"data": result})
}

