	}

	var statesJSON []byte
	err := db.DB.QueryRow(`SELECT function_states FROM locations WHERE location_id=$1`, req.LocationID).Scan(&statesJSON)
	if err != nil {
		writeError(w, 404, "not_found", "Location not found")
		return
	}

	var states map[string]bool
	if statesJSON != nil {
		json.Unmarshal(statesJSON, &states)
	}
	if states == nil {
		states = map[string]bool{}
	}
	states[req.Function] = req.Active
	newStates, _ := json.Marshal(states)

	db.DB.Exec(`UPDATE locations SET function_states=$1, updated_at=NOW() WHERE location_id=$2`, newStates, req.LocationID)

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{"locationId": req.LocationID, "function": req.Function, "active": req.Active},
	})
}

