		return
	}
	if req.ConfirmationSide == "receiver" && userID != receiverID {
		writeError(w, 403, "forbidden", "You are not the receiver")
		return
	}

	if req.ConfirmationSide == "sender" {
		if senderConfirmed {
			writeError(w, 409, "concurrent_conflict", "Already confirmed by sender")
			return
		}
		db.DB.Exec(`UPDATE handoffs SET sender_confirmed=true, confirmed_by_sender_at=$1 WHERE handoff_id=$2`, req.ConfirmedAt, req.HandoffID)
	} else {
		if receiverConfirmed {
			writeError(w, 409, "concurrent_conflict", "Already confirmed by receiver")
			return
		}
		db.DB.Exec(`UPDATE handoffs SET receiver_confirmed=true, confirmed_by_receiver_at=$1 WHERE handoff_id=$2`, req.ConfirmedAt, req.HandoffID)
	}

	// Check if both confirmed
	db.DB.QueryRow(`SELECT sender_confirmed, receiver_confirmed FROM handoffs WHERE handoff_id=$1`, req.HandoffID).Scan(&senderConfirmed, &receiverConfirmed)

	if senderConfirmed && receiverConfirmed {
		// Complete the handoff - transfer custody
		var sampleID string
		db.DB.QueryRow(`SELECT sample_id FROM handoffs WHERE handoff_id=$1`, req.HandoffID).Scan(&sampleID)
		db.DB.Exec(`UPDATE samples SET current_holder_id=$1, updated_at=NOW() WHERE sample_id=$2`, receiverID, sampleID)
		db.DB.Exec(`UPDATE handoffs SET status='completed', completed_at=$1 WHERE handoff_id=$2`, req.ConfirmedAt, req.HandoffID)
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"handoffId":        req.HandoffID,
			"confirmationSide": req.ConfirmationSide,
			"confirmed":        true,
		},
	})
}

