// POST /api/read-operations-state
func ReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator") {
		writeError(w, 403, "forbidden", "Must be dispatcher or admin")
		return
	}

	var req struct {
		Filters map[string]any `json:"filters"`
	}
	mustJSON(r, &req)

	state := models.OperationsState{
		Samples:    []map[string]any{},
		Workers:    []map[string]any{},
		Locations:  []models.OperationsLocation{},
		Connections: []models.OperationsConnection{},
		Routes:     []map[string]any{},
		Handoffs:   []map[string]any{},
		Delays:     []map[string]any{},
		Exceptions: []map[string]any{},
	}

	// Samples
	samplesRows, _ := db.DB.Query(`
		SELECT sample_id, COALESCE(request_id::text,''), status, origin_lat, origin_lng, delivery_deadline::text,
			COALESCE(current_holder_id::text,''), COALESCE(active_journey_id::text,''),
			COALESCE(current_location_lat, 0), COALESCE(current_location_lng, 0),
			COALESCE(location_recorded_at::text, ''), exception
		FROM samples ORDER BY created_at DESC LIMIT 500`)
	if samplesRows != nil {
		defer samplesRows.Close()
		for samplesRows.Next() {
			var id, rid, status, deadline, holder, journey, locAt string
			var oLat, oLng, cLat, cLng float64
			var exc bool
			samplesRows.Scan(&id, &rid, &status, &oLat, &oLng, &deadline, &holder, &journey, &cLat, &cLng, &locAt, &exc)
			stale := true
			if locAt != "" {
				t, err := time.Parse(time.RFC3339, locAt)
				if err == nil {
					stale = time.Since(t) > 15*time.Minute
				}
			}
			entry := map[string]any{
				"sampleId":           id,
				"status":             status,
				"origin":             models.Coordinate{Lat: oLat, Lng: oLng},
				"deliveryDeadline":   deadline,
				"currentHolderId":    holder,
				"activeJourneyId":    journey,
				"latestLocation":     models.Coordinate{Lat: cLat, Lng: cLng},
				"locationRecordedAt": locAt,
				"locationStale":      stale,
			}
			if exc {
				entry["exception"] = true
			}
			state.Samples = append(state.Samples, entry)
		}
	}

	// Workers
	workersRows, _ := db.DB.Query(`SELECT user_id, full_name, roles, active FROM users WHERE active=true`)
	if workersRows != nil {
		defer workersRows.Close()
		for workersRows.Next() {
			var wid, name string
			var rolesJSON []byte
			var active bool
			workersRows.Scan(&wid, &name, &rolesJSON, &active)
			var roles []string
			json.Unmarshal(rolesJSON, &roles)
			var count int
			db.DB.QueryRow(`SELECT COUNT(*) FROM assignments WHERE worker_id=$1`, wid).Scan(&count)

			var wlLat, wlLng float64
			var wlRecAt string
			wlStale := true
			err := db.DB.QueryRow(`SELECT lat, lng, recorded_at::text FROM worker_locations WHERE worker_id=$1`, wid).
				Scan(&wlLat, &wlLng, &wlRecAt)
			if err == nil && wlRecAt != "" {
				t, err := time.Parse(time.RFC3339, wlRecAt)
				if err == nil {
					wlStale = time.Since(t) > 15*time.Minute
				}
			}

			state.Workers = append(state.Workers, map[string]any{
				"workerId":        wid,
				"fullName":        name,
				"roles":           roles,
				"available":       active,
				"status":          "available",
				"capacityUnits":   10,
				"assignmentCount": count,
				"latestLocation":  models.Coordinate{Lat: wlLat, Lng: wlLng},
				"locationStale":   wlStale,
			})
		}
	}

	// Locations
	locRows, _ := db.DB.Query(`SELECT location_id, name, lat, lng, active, functions FROM locations`)
	if locRows != nil {
		defer locRows.Close()
		for locRows.Next() {
			var l models.OperationsLocation
			var lat, lng float64
			var funcJSON []byte
			locRows.Scan(&l.LocationID, &l.Name, &lat, &lng, &l.Active, &funcJSON)
			json.Unmarshal(funcJSON, &l.Functions)
			l.Coordinate = models.Coordinate{Lat: lat, Lng: lng}
			state.Locations = append(state.Locations, l)
		}
	}

	// Connections
	connRows, _ := db.DB.Query(`SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
	if connRows != nil {
		defer connRows.Close()
		for connRows.Next() {
			var c models.OperationsConnection
			connRows.Scan(&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active)
			state.Connections = append(state.Connections, c)
		}
	}

	// Handoffs
	handoffRows, _ := db.DB.Query(`SELECT handoff_id, sample_id, status FROM handoffs LIMIT 200`)
	if handoffRows != nil {
		defer handoffRows.Close()
		for handoffRows.Next() {
			var hid, sid, st string
			handoffRows.Scan(&hid, &sid, &st)
			state.Handoffs = append(state.Handoffs, map[string]any{"handoffId": hid, "sampleId": sid, "status": st})
		}
	}

	// Exceptions
	excRows, _ := db.DB.Query(`SELECT sample_id, exception_reason FROM samples WHERE exception=true LIMIT 200`)
	if excRows != nil {
		defer excRows.Close()
		for excRows.Next() {
			var sid, reason string
			excRows.Scan(&sid, &reason)
			state.Exceptions = append(state.Exceptions, map[string]any{"sampleId": sid, "reason": reason})
		}
	}

	writeJSON(w, 200, map[string]any{"data": state})
}

// POST /api/read-journey-plan
func ReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	plan := buildJourneyPlan(req.JourneyID)
	if plan == nil {
		writeError(w, 404, "not_found", "Journey not found")
		return
	}

	writeJSON(w, 200, map[string]any{"data": plan})
}

func buildJourneyPlan(journeyID string) *models.JourneyPlan {
	var j models.Journey
	err := db.DB.QueryRow(`
		SELECT journey_id, sample_id, plan_version, status, COALESCE(current_holder_id::text,''), delivery_deadline::text
		FROM journeys WHERE journey_id=$1`, journeyID).
		Scan(&j.JourneyID, &j.SampleID, &j.PlanVersion, &j.Status, &j.CurrentHolderID, &j.DeliveryDeadline)
	if err != nil {
		return nil
	}

	plan := &models.JourneyPlan{
		JourneyID:        j.JourneyID,
		PlanVersion:      j.PlanVersion,
		SampleID:         j.SampleID,
		Status:           j.Status,
		DeliveryDeadline: j.DeliveryDeadline,
		Stops:            []models.JourneyStop{},
		Legs:             []models.JourneyLeg{},
	}

	// Get stops
	stopRows, _ := db.DB.Query(`
		SELECT stop_id, sequence, COALESCE(location_id::text,''), lat, lng, COALESCE(arrive_by::text,''), COALESCE(depart_by::text,''), status, COALESCE(completed_at::text,'')
		FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if stopRows != nil {
		defer stopRows.Close()
		for stopRows.Next() {
			var s models.JourneyStop
			stopRows.Scan(&s.StopID, &s.Sequence, &s.LocationID, &s.Coordinate.Lat, &s.Coordinate.Lng, &s.ArriveBy, &s.DepartBy, &s.Status, &s.CompletedAt)
			plan.Stops = append(plan.Stops, s)
		}
	}

	// Get legs
	legRows, _ := db.DB.Query(`
		SELECT leg_id, sequence, from_stop_id, to_stop_id, COALESCE(assignment_id::text,''), COALESCE(worker_id::text,''), status, kind, COALESCE(deadline::text,''), cooled_required, COALESCE(completed_at::text,'')
		FROM journey_legs WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if legRows != nil {
		defer legRows.Close()
		for legRows.Next() {
			var l models.JourneyLeg
			legRows.Scan(&l.LegID, &l.Sequence, &l.FromStopID, &l.ToStopID, &l.AssignmentID, &l.WorkerID, &l.Status, &l.Kind, &l.Deadline, &l.CooldownRequired, &l.CompletedAt)
			plan.Legs = append(plan.Legs, l)
		}
	}

	return plan
}

// POST /api/cancel-journey
func CancelJourney(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator") {
		writeError(w, 403, "forbidden", "Must be dispatcher or admin")
		return
	}

	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	// Version check
	var currentVersion int
	db.DB.QueryRow(`SELECT plan_version FROM journeys WHERE journey_id=$1`, req.JourneyID).Scan(&currentVersion)
	if currentVersion != req.ExpectedPlanVersion {
		writeError(w, 409, "state_snapshot_changed", "Plan version mismatch")
		return
	}

	db.DB.Exec(`UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=NOW() WHERE journey_id=$1`, req.JourneyID)

	// Release capacity reservations, update assignment statuses
	db.DB.Exec(`UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status != 'completed'`, req.JourneyID)

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{"journeyId": req.JourneyID, "status": "cancelled"},
	})
}

