func ConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "laboratory_intake_operator", "administrator") {
		writeError(w, 403, "forbidden", "Must be lab intake operator")
		return
	}

	var req struct {
		SampleID     string `json:"sampleId"`
		LaboratoryID string `json:"laboratoryId"`
		ReceivedAt   string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	_, err := db.DB.Exec(`
		UPDATE samples SET status='received', current_holder_id=$1, updated_at=NOW() WHERE sample_id=$2 AND status != 'received'`,
		currentUserID(r), req.SampleID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to confirm receipt")
		return
	}

	// Complete the active journey
	db.DB.Exec(`UPDATE journeys SET status='completed', updated_at=NOW() WHERE sample_id=$1 AND status != 'completed'`, req.SampleID)

	writeJSON(w, 201, map[string]any{
		"data": map[string]any{
			"sampleId":     req.SampleID,
			"laboratoryId": req.LaboratoryID,
			"status":       "received",
		},
	})
}

// POST /api/record-handling-checkpoint
func RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	if !hasRole(r, "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator") {
		writeError(w, 403, "forbidden", "Not authorized")
		return
	}

	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		LocationID           string  `json:"locationId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		RecordedAt           string  `json:"recordedAt"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	// Check temperature
	var tempMin, tempMax float64
	err := db.DB.QueryRow(`SELECT temperature_min_c, temperature_max_c FROM samples WHERE sample_id=$1`, req.SampleID).
		Scan(&tempMin, &tempMax)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}

	exception := false
	if req.ObservedTemperatureC < tempMin || req.ObservedTemperatureC > tempMax {
		exception = true
		db.DB.Exec(`UPDATE samples SET exception=true, exception_reason='Temperature out of range at checkpoint' WHERE sample_id=$1`, req.SampleID)
	}

	auditLog(currentUserID(r), selectedRole(r), "handling_checkpoint", "sample", req.SampleID, true,
		fmt.Sprintf(`{"containerType":"%s","temperature":%f,"exception":%v}`, req.ContainerType, req.ObservedTemperatureC, exception),
		"Handling checkpoint recorded")

	writeJSON(w, 201, map[string]any{
		"data": map[string]any{
			"sampleId":             req.SampleID,
			"exception":            exception,
			"observedTemperatureC": req.ObservedTemperatureC,
		},
	})
}

