// POST /api/split-journey
func SplitJourney(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator") {
		writeError(w, 403, "forbidden", "Must be dispatcher or admin")
		return
	}

	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIds           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	var currentVersion int
	db.DB.QueryRow(`SELECT plan_version FROM journeys WHERE journey_id=$1`, req.JourneyID).Scan(&currentVersion)
	if currentVersion != req.ExpectedPlanVersion {
		writeError(w, 409, "state_snapshot_changed", "Plan version mismatch")
		return
	}

	// Increment version
	db.DB.Exec(`UPDATE journeys SET plan_version=plan_version+1, updated_at=NOW() WHERE journey_id=$1`, req.JourneyID)

	// Create new journeys for the split samples
	var newJourneyIDs []string
	for _, sampleID := range req.SampleIds {
		var deadline string
		db.DB.QueryRow(`SELECT delivery_deadline::text FROM samples WHERE sample_id=$1`, sampleID).Scan(&deadline)
		var newID string
		db.DB.QueryRow(`INSERT INTO journeys (sample_id, status, delivery_deadline) VALUES ($1, 'planned', $2) RETURNING journey_id`, sampleID, deadline).Scan(&newID)
		newJourneyIDs = append(newJourneyIDs, newID)
		db.DB.Exec(`UPDATE samples SET active_journey_id=$1 WHERE sample_id=$2`, newID, sampleID)
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"journeyId":       req.JourneyID,
			"newJourneyIds":   newJourneyIDs,
			"status":          "split",
		},
	})
}

// POST /api/merge-journeys
func MergeJourneys(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator") {
		writeError(w, 403, "forbidden", "Must be dispatcher or admin")
		return
	}

	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIds    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	var currentVersion int
	db.DB.QueryRow(`SELECT plan_version FROM journeys WHERE journey_id=$1`, req.TargetJourneyID).Scan(&currentVersion)
	if currentVersion != req.ExpectedPlanVersion {
		writeError(w, 409, "state_snapshot_changed", "Plan version mismatch")
		return
	}

	db.DB.Exec(`UPDATE journeys SET plan_version=plan_version+1, updated_at=NOW() WHERE journey_id=$1`, req.TargetJourneyID)

	// Cancel source journeys, move samples to target
	for _, srcID := range req.SourceJourneyIds {
		var sampleID string
		db.DB.QueryRow(`SELECT sample_id FROM journeys WHERE journey_id=$1`, srcID).Scan(&sampleID)
		db.DB.Exec(`UPDATE samples SET active_journey_id=$1 WHERE sample_id=$2`, req.TargetJourneyID, sampleID)
		db.DB.Exec(`UPDATE journeys SET status='merged', plan_version=plan_version+1 WHERE journey_id=$1`, srcID)
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"journeyId": req.TargetJourneyID,
			"status":    "merged",
		},
	})
}

