func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(map[string]string{"error": msg, "code": code})
}

func mustJSON(r *http.Request, v any) error {
	return json.NewDecoder(r.Body).Decode(v)
}

func currentUserID(r *http.Request) string {
	c := middleware.GetClaims(r)
	if c == nil {
		return ""
	}
	return c.UserID
}

func currentRoles(r *http.Request) []string {
	c := middleware.GetClaims(r)
	if c == nil {
		return nil
	}
	return c.Roles
}

func selectedRole(r *http.Request) string {
	c := middleware.GetClaims(r)
	if c == nil {
		return ""
	}
	return c.SelectedRole
}

func hasRole(r *http.Request, roles ...string) bool {
	userRoles := currentRoles(r)
	for _, ur := range userRoles {
		if ur == "administrator" {
			return true
		}
		for _, want := range roles {
			if ur == want {
				return true
			}
		}
	}
	return false
}

func requireRole(r *http.Request, roles ...string) bool {
	if !hasRole(r, roles...) {
		return false
	}
	sr := selectedRole(r)
	for _, want := range roles {
		if sr == want {
			return true
		}
	}
	return hasRole(r, "administrator") && sr == "administrator"
}

func auditLog(actorID, role, action, entityType, entityID string, success bool, changes, details string) {
	_, err := db.DB.Exec(`
		INSERT INTO audit_log (actor_id, role, action, entity_type, entity_id, success, changes, details)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
		actorID, role, action, entityType, entityID, success, changes, details)
	if err != nil {
		log.Printf("Audit log error: %v", err)
	}
}

func publishEvent(eventType, audience string, payload any) {
	data, _ := json.Marshal(payload)
	_, err := db.DB.Exec(`INSERT INTO events (event_type, audience, payload) VALUES ($1, $2, $3)`,
		eventType, audience, string(data))
	if err != nil {
		log.Printf("Event publish error: %v", err)
	}
}

// POST /api/authenticate-user
func AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	var userID, username, passwordHash string
	var rolesJSON []byte
	err := db.DB.QueryRow(`SELECT user_id, username, password_hash, roles FROM users WHERE username = $1 AND active = true`, req.Username).
		Scan(&userID, &username, &passwordHash, &rolesJSON)
	if err == sql.ErrNoRows {
		writeError(w, 401, "unauthorized", "Invalid credentials")
		return
	}
	if err != nil {
		writeError(w, 500, "internal_error", "Database error")
		return
	}

	if err := auth.CheckPassword(req.Password, passwordHash); err != nil {
		auditLog(userID, "any", "login", "user", userID, false, "{}", "Invalid password")
		writeError(w, 401, "unauthorized", "Invalid credentials")
		return
	}

	var roles []string
	json.Unmarshal(rolesJSON, &roles)

	selectedRole := ""
	if len(roles) > 0 {
		selectedRole = roles[0]
	}

	token, err := auth.GenerateToken(userID, username, roles, selectedRole)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to generate token")
		return
	}

	auditLog(userID, selectedRole, "login", "user", userID, true, "{}", "Successful login")

	writeJSON(w, 201, map[string]any{
		"data": map[string]any{
			"token":        token,
			"userId":       userID,
			"username":     username,
			"roles":        roles,
			"selectedRole": selectedRole,
		},
	})
}

// POST /api/select-active-role
func SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	if claims == nil {
		writeError(w, 401, "unauthorized", "Not authenticated")
		return
	}

	var req struct {
		Role string `json:"role"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	found := false
	for _, role := range claims.Roles {
		if role == req.Role {
			found = true
			break
		}
	}
	if !found {
		writeError(w, 400, "invalid_json", "Role not assigned to user")
		return
	}

	claims.SelectedRole = req.Role
	token, err := auth.GenerateToken(claims.UserID, claims.Username, claims.Roles, req.Role)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to regenerate token")
		return
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"token":        token,
			"userId":       claims.UserID,
			"username":     claims.Username,
			"roles":        claims.Roles,
			"selectedRole": req.Role,
		},
	})
}

