// POST /api/read-sample-lifecycle
func ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID string `json:"sampleId"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	var s models.Sample
	var originLat, originLng float64
	var currentLat, currentLng sql.NullFloat64
	err := db.DB.QueryRow(`
		SELECT sample_id, request_id, sample_type_id, status, origin_lat, origin_lng, delivery_deadline::text,
			current_holder_id, current_location_lat, current_location_lng, location_recorded_at::text,
			active_journey_id, exception
		FROM samples WHERE sample_id=$1`, req.SampleID).
		Scan(&s.SampleID, &s.RequestID, &s.SampleTypeID, &s.Status, &originLat, &originLng,
			&s.DeliveryDeadline, &s.CurrentHolderID, &currentLat, &currentLng, &s.LocationRecordedAt,
			&s.ActiveJourneyID, &s.Exception)
	if err == sql.ErrNoRows {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}
	if err != nil {
		writeError(w, 500, "internal_error", "Database error")
		return
	}

	s.Origin = models.Coordinate{Lat: originLat, Lng: originLng}
	if currentLat.Valid {
		s.LatestLocation = models.Coordinate{Lat: currentLat.Float64, Lng: currentLng.Float64}
	}
	// Determine stale
	if s.LocationRecordedAt != "" {
		recordedAt, _ := time.Parse(time.RFC3339, s.LocationRecordedAt)
		s.LocationStale = time.Since(recordedAt) > 15*time.Minute
	} else {
		s.LocationStale = true
	}

	// Get audit history for timeline
	rows, err := db.DB.Query(`
		SELECT action, timestamp::text FROM audit_log
		WHERE entity_type='sample' AND entity_id=$1
		ORDER BY timestamp ASC`, req.SampleID)
	history := []models.TimelineEntry{}
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var action, ts string
			rows.Scan(&action, &ts)
			history = append(history, models.TimelineEntry{
				Status:     action,
				OccurredAt: ts,
			})
		}
	}

	lifecycle := models.SampleLifecycle{
		SampleID: s.SampleID,
		Status:   s.Status,
		History:  history,
		Sample:   &s,
	}

	writeJSON(w, 200, map[string]any{"data": lifecycle})
}

