// POST /api/report-disruption
func ReportDisruption(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator", "node_handler") {
		writeError(w, 403, "forbidden", "Must be dispatcher, admin, or node handler")
		return
	}

	var req struct {
		ResourceType string `json:"resourceType"`
		ResourceID   string `json:"resourceId"`
		Reason       string `json:"reason"`
		OccurredAt   string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	// Mark affected samples/journeys as disrupted
	switch req.ResourceType {
	case "location":
		db.DB.Exec(`UPDATE locations SET active=false WHERE location_id=$1`, req.ResourceID)
	case "connection":
		db.DB.Exec(`UPDATE connections SET active=false WHERE connection_id=$1`, req.ResourceID)
	}

	// Mark affected active journeys for replanning
	db.DB.Exec(`UPDATE journeys SET status='replanned', plan_version=plan_version+1, updated_at=NOW() WHERE status IN ('planned', 'in_progress')`)

	auditLog(currentUserID(r), selectedRole(r), "report_disruption", req.ResourceType, req.ResourceID, true, mustJSONStr(req), "")

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"disruptionId": auth.GenerateID(),
			"resourceType": req.ResourceType,
			"resourceId":   req.ResourceID,
			"reported":     true,
		},
	})
}

// POST /api/search-audit-trail
func SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator") {
		writeError(w, 403, "forbidden", "Must be dispatcher or admin")
		return
	}

	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}

	orderClause := "timestamp DESC"
	if req.Order == "oldest_first" {
		orderClause = "timestamp ASC"
	}

	// Build query with filters
	conditions := []string{"1=1"}
	args := []any{}
	argN := 1

	if req.ActorID != "" {
		conditions = append(conditions, fmt.Sprintf("actor_id=$%d", argN))
		args = append(args, req.ActorID)
		argN++
	}
	if req.EntityType != "" {
		conditions = append(conditions, fmt.Sprintf("entity_type=$%d", argN))
		args = append(args, req.EntityType)
		argN++
	}
	if req.EntityID != "" {
		conditions = append(conditions, fmt.Sprintf("entity_id=$%d", argN))
		args = append(args, req.EntityID)
		argN++
	}
	if req.Action != "" {
		conditions = append(conditions, fmt.Sprintf("action=$%d", argN))
		args = append(args, req.Action)
		argN++
	}
	if req.Role != "" {
		conditions = append(conditions, fmt.Sprintf("role=$%d", argN))
		args = append(args, req.Role)
		argN++
	}
	if req.Success != nil {
		conditions = append(conditions, fmt.Sprintf("success=$%d", argN))
		args = append(args, *req.Success)
		argN++
	}
	if req.FromTime != "" {
		conditions = append(conditions, fmt.Sprintf("timestamp >= $%d", argN))
		args = append(args, req.FromTime)
		argN++
	}
	if req.ToTime != "" {
		conditions = append(conditions, fmt.Sprintf("timestamp <= $%d", argN))
		args = append(args, req.ToTime)
		argN++
	}

	whereClause := strings.Join(conditions, " AND ")

	// Count total
	var total int
	countQuery := fmt.Sprintf("SELECT COUNT(*) FROM audit_log WHERE %s", whereClause)
	db.DB.QueryRow(countQuery, args...).Scan(&total)

	// Fetch entries
	query := fmt.Sprintf(`
		SELECT audit_id, COALESCE(actor_id::text,''), role, action, entity_type, entity_id, success, changes::text, details, timestamp::text
		FROM audit_log WHERE %s ORDER BY %s LIMIT $%d OFFSET $%d`,
		whereClause, orderClause, argN, argN+1)
	args = append(args, req.Limit, req.Offset)

	rows, err := db.DB.Query(query, args...)
	if err != nil {
		writeError(w, 500, "internal_error", "Query failed")
		return
	}
	defer rows.Close()

	entries := []models.AuditEntry{}
	for rows.Next() {
		var e models.AuditEntry
		var changesStr string
		rows.Scan(&e.AuditID, &e.ActorID, &e.Role, &e.Action, &e.EntityType, &e.EntityID, &e.Success, &changesStr, &e.Details, &e.Timestamp)
		json.Unmarshal([]byte(changesStr), &e.Changes)
		entries = append(entries, e)
	}

	hasMore := total > req.Offset+req.Limit
	nextOffset := 0
	if hasMore {
		nextOffset = req.Offset + req.Limit
	}

	result := models.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     req.Offset,
		Limit:      req.Limit,
		Order:      req.Order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}

	writeJSON(w, 200, map[string]any{"data": result})
}

// POST /api/read-serviceability-snapshot
func ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	var version string
	var computedAt string
	var dataJSON []byte
	err := db.DB.QueryRow(`SELECT version::text, computed_at::text, data FROM serviceability_snapshots ORDER BY computed_at DESC LIMIT 1`).
		Scan(&version, &computedAt, &dataJSON)
	if err == sql.ErrNoRows {
		// No snapshot yet - return empty region
		writeJSON(w, 200, map[string]any{
			"data": models.ServiceabilityRegion{
				Version:    auth.GenerateID(),
				ComputedAt: time.Now().UTC().Format(time.RFC3339),
				Regions:    []models.ServiceabilityPolygon{},
				Serviceable: false,
			},
		})
		return
	}
	if err != nil {
		writeError(w, 500, "internal_error", "Database error")
		return
	}

	var region models.ServiceabilityRegion
	json.Unmarshal(dataJSON, &region)
	region.Version = version
	region.ComputedAt = computedAt

	writeJSON(w, 200, map[string]any{"data": region})
}

// POST /api/set-worker-availability
func SetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "administrator") {
		writeError(w, 403, "forbidden", "Admin only")
		return
	}

	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	db.DB.Exec(`UPDATE users SET active=$1, updated_at=NOW() WHERE user_id=$2`, req.Available, req.WorkerID)

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{"workerId": req.WorkerID, "available": req.Available},
	})
}

// GET /api/ui/bootstrap
func UIBootstrap(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	if claims == nil {
		writeError(w, 401, "unauthorized", "Not authenticated")
		return
	}

	// Gather UI bootstrap data: user info, sample types, locations, connections
	sampleTypes := []models.SampleType{}
	rows, _ := db.DB.Query(`SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed FROM sample_types`)
	if rows != nil {
		defer rows.Close()
		for rows.Next() {
			var st models.SampleType
			var incompJSON []byte
			rows.Scan(&st.SampleTypeID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &incompJSON, &st.RequiresCooledRoute, &st.BatchingAllowed)
			json.Unmarshal(incompJSON, &st.IncompatibleSampleTypes)
			sampleTypes = append(sampleTypes, st)
		}
	}

	locations := []models.Location{}
	locRows, _ := db.DB.Query(`SELECT location_id, name, lat, lng, coverage_km, handling_minutes, active, functions FROM locations`)
	if locRows != nil {
		defer locRows.Close()
		for locRows.Next() {
			var loc models.Location
			var funcJSON []byte
			locRows.Scan(&loc.LocationID, &loc.Name, &loc.Coordinate.Lat, &loc.Coordinate.Lng, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &funcJSON)
			json.Unmarshal(funcJSON, &loc.Functions)
			locations = append(locations, loc)
		}
	}

	var certJSON []byte
	var fullName string
	db.DB.QueryRow(`SELECT full_name, certifications FROM users WHERE user_id=$1`, claims.UserID).Scan(&fullName, &certJSON)
	var certs []models.Certification
	if certJSON != nil {
		json.Unmarshal(certJSON, &certs)
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"user": map[string]any{
				"userId":         claims.UserID,
				"username":       claims.Username,
				"fullName":       fullName,
				"roles":          claims.Roles,
				"selectedRole":   claims.SelectedRole,
				"certifications": certs,
			},
			"sampleTypes": sampleTypes,
			"locations":   locations,
		},
	})
}

// GET /api/events (SSE stream)
func StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	// This is a simplified SSE implementation
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, 500, "internal_error", "Streaming not supported")
		return
	}

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("Access-Control-Allow-Origin", "*")

	since := r.URL.Query().Get("since")
	sinceSeq := int64(0)
	if since != "" {
		sinceSeq, _ = strconv.ParseInt(since, 10, 64)
	}

	// Send existing events since sequence
	rows, err := db.DB.Query(`SELECT event_id, sequence, event_type, audience, payload, timestamp::text FROM events WHERE sequence > $1 ORDER BY sequence ASC`, sinceSeq)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var e models.RealtimeEvent
			var payloadJSON []byte
			rows.Scan(&e.EventID, &e.Sequence, &e.EventType, &e.Audience, &payloadJSON, &e.Timestamp)
			json.Unmarshal(payloadJSON, &e.Payload)
			data, _ := json.Marshal(e)
			fmt.Fprintf(w, "data: %s\n\n", data)
			flusher.Flush()
		}
	}

	// Keep connection open for new events
	lastSeq := sinceSeq
	for {
		var e models.RealtimeEvent
		var payloadJSON []byte
		err := db.DB.QueryRow(`SELECT event_id, sequence, event_type, audience, payload, timestamp::text FROM events WHERE sequence > $1 ORDER BY sequence ASC LIMIT 1`, lastSeq).
			Scan(&e.EventID, &e.Sequence, &e.EventType, &e.Audience, &payloadJSON, &e.Timestamp)
		if err == sql.ErrNoRows {
			time.Sleep(2 * time.Second)
			continue
		}
		if err != nil {
			break
		}
		json.Unmarshal(payloadJSON, &e.Payload)
		data, _ := json.Marshal(e)
		fmt.Fprintf(w, "data: %s\n\n", data)
		flusher.Flush()
		lastSeq = e.Sequence
	}
}

// GET /ready
func SystemReadiness(w http.ResponseWriter, r *http.Request) {
	if err := db.DB.Ping(); err != nil {
		writeJSON(w, 503, map[string]string{"status": "not_ready", "error": err.Error()})
		return
	}
	writeJSON(w, 200, map[string]string{"status": "ready"})
}

// Helpers

func haversine(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * 0.017453292519943295
	dLng := (lng2 - lng1) * 0.017453292519943295
	a := sin(dLat/2)*sin(dLat/2) + cos(lat1*0.017453292519943295)*cos(lat2*0.017453292519943295)*sin(dLng/2)*sin(dLng/2)
	c := 2 * atan2(sqrt(a), sqrt(1-a))
	return R * c
}

func sin(x float64) float64 {
	// Simple Taylor series for sin
	return x - x*x*x/6 + x*x*x*x*x/120 - x*x*x*x*x*x*x/5040
}

func cos(x float64) float64 {
	return sin(1.5707963267948966 - x)
}

func sqrt(x float64) float64 {
	if x <= 0 {
		return 0
	}
	z := x
	for i := 0; i < 100; i++ {
		z -= (z*z - x) / (2 * z)
	}
	return z
}

func atan2(y, x float64) float64 {
	if x > 0 {
		return atan(y / x)
	}
	if x < 0 && y >= 0 {
		return atan(y/x) + 3.141592653589793
	}
	if x < 0 && y < 0 {
		return atan(y/x) - 3.141592653589793
	}
	if x == 0 && y > 0 {
		return 1.5707963267948966
	}
	if x == 0 && y < 0 {
		return -1.5707963267948966
	}
	return 0
}

func atan(x float64) float64 {
	return x - x*x*x/3 + x*x*x*x*x/5 - x*x*x*x*x*x*x/7
}

func mustJSONStr(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

