// POST /api/collect-and-seal-sample
func CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "certified_collection_professional", "administrator") {
		writeError(w, 403, "forbidden", "Must be certified collection professional")
		return
	}

	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		CollectedAt          string  `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	// Verify assignment belongs to current user
	var workerID, assignmentStatus, sampleStatus string
	err := db.DB.QueryRow(`SELECT worker_id, status FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
		Scan(&workerID, &assignmentStatus)
	if err == sql.ErrNoRows {
		writeError(w, 404, "not_found", "Assignment not found")
		return
	}
	if err != nil {
		writeError(w, 500, "internal_error", "Database error")
		return
	}
	if workerID != currentUserID(r) {
		writeError(w, 403, "ineligible_worker", "Not your assignment")
		return
	}
	if assignmentStatus != "accepted" {
		writeError(w, 409, "assignment_inactive", "Assignment not in accepable state")
		return
	}

	// Update sample
	_, err = db.DB.Exec(`
		UPDATE samples SET status='collected', collected_at=$1, sealed=true, container_type=$2, current_holder_id=$3, updated_at=NOW()
		WHERE sample_id=$4`,
		req.CollectedAt, req.ContainerType, currentUserID(r), req.SampleID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update sample")
		return
	}

	// Update assignment
	db.DB.Exec(`UPDATE assignments SET status='in_progress', updated_at=NOW() WHERE assignment_id=$1`, req.AssignmentID)

	// Check temperature
	sampleStatus = "collected"
	var tempMin, tempMax float64
	db.DB.QueryRow(`SELECT temperature_min_c, temperature_max_c FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&tempMin, &tempMax)
	if req.ObservedTemperatureC < tempMin || req.ObservedTemperatureC > tempMax {
		db.DB.Exec(`UPDATE samples SET exception=true, exception_reason='Temperature out of range' WHERE sample_id=$1`, req.SampleID)
		sampleStatus = "exception"
	}

	auditLog(currentUserID(r), selectedRole(r), "collect_and_seal", "sample", req.SampleID, true, mustJSONStr(req), "")

	writeJSON(w, 201, map[string]any{
		"data": map[string]any{
			"sampleId":    req.SampleID,
			"assignmentId": req.AssignmentID,
			"status":      sampleStatus,
		},
	})
}

