	var dataJSON []byte
	err := db.DB.QueryRow(`SELECT version::text, computed_at::text, data FROM serviceability_snapshots ORDER BY computed_at DESC LIMIT 1`).
		Scan(&version, &computedAt, &dataJSON)
	if err == sql.ErrNoRows {
		// No snapshot yet - return empty region
		writeJSON(w, 200, map[string]any{
			"data": models.ServiceabilityRegion{
				Version:    auth.GenerateID(),
				ComputedAt: time.Now().UTC().Format(time.RFC3339),
				Regions:    []models.ServiceabilityPolygon{},
				Serviceable: false,
			},
		})
		return
	}
	if err != nil {
		writeError(w, 500, "internal_error", "Database error")
		return
	}

	var region models.ServiceabilityRegion
	json.Unmarshal(dataJSON, &region)
	region.Version = version
	region.ComputedAt = computedAt

	writeJSON(w, 200, map[string]any{"data": region})
}

