// GET /api/ui/bootstrap
func UIBootstrap(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	if claims == nil {
		writeError(w, 401, "unauthorized", "Not authenticated")
		return
	}

	// Gather UI bootstrap data: user info, sample types, locations, connections
	sampleTypes := []models.SampleType{}
	rows, _ := db.DB.Query(`SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed FROM sample_types`)
	if rows != nil {
		defer rows.Close()
		for rows.Next() {
			var st models.SampleType
			var incompJSON []byte
			rows.Scan(&st.SampleTypeID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &incompJSON, &st.RequiresCooledRoute, &st.BatchingAllowed)
			json.Unmarshal(incompJSON, &st.IncompatibleSampleTypes)
			sampleTypes = append(sampleTypes, st)
		}
	}

	locations := []models.Location{}
	locRows, _ := db.DB.Query(`SELECT location_id, name, lat, lng, coverage_km, handling_minutes, active, functions FROM locations`)
	if locRows != nil {
		defer locRows.Close()
		for locRows.Next() {
			var loc models.Location
			var funcJSON []byte
			locRows.Scan(&loc.LocationID, &loc.Name, &loc.Coordinate.Lat, &loc.Coordinate.Lng, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &funcJSON)
			json.Unmarshal(funcJSON, &loc.Functions)
			locations = append(locations, loc)
		}
	}

	var certJSON []byte
	var fullName string
	db.DB.QueryRow(`SELECT full_name, certifications FROM users WHERE user_id=$1`, claims.UserID).Scan(&fullName, &certJSON)
	var certs []models.Certification
	if certJSON != nil {
		json.Unmarshal(certJSON, &certs)
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"user": map[string]any{
				"userId":         claims.UserID,
				"username":       claims.Username,
				"fullName":       fullName,
				"roles":          claims.Roles,
				"selectedRole":   claims.SelectedRole,
				"certifications": certs,
			},
			"sampleTypes": sampleTypes,
			"locations":   locations,
		},
	})
}

// GET /api/events (SSE stream)
func StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	// This is a simplified SSE implementation
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, 500, "internal_error", "Streaming not supported")
		return
	}

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("Access-Control-Allow-Origin", "*")

	since := r.URL.Query().Get("since")
	sinceSeq := int64(0)
	if since != "" {
		sinceSeq, _ = strconv.ParseInt(since, 10, 64)
	}

	// Send existing events since sequence
	rows, err := db.DB.Query(`SELECT event_id, sequence, event_type, audience, payload, timestamp::text FROM events WHERE sequence > $1 ORDER BY sequence ASC`, sinceSeq)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var e models.RealtimeEvent
			var payloadJSON []byte
			rows.Scan(&e.EventID, &e.Sequence, &e.EventType, &e.Audience, &payloadJSON, &e.Timestamp)
			json.Unmarshal(payloadJSON, &e.Payload)
			data, _ := json.Marshal(e)
			fmt.Fprintf(w, "data: %s\n\n", data)
			flusher.Flush()
		}
	}

	// Keep connection open for new events
	lastSeq := sinceSeq
	for {
		var e models.RealtimeEvent
		var payloadJSON []byte
		err := db.DB.QueryRow(`SELECT event_id, sequence, event_type, audience, payload, timestamp::text FROM events WHERE sequence > $1 ORDER BY sequence ASC LIMIT 1`, lastSeq).
			Scan(&e.EventID, &e.Sequence, &e.EventType, &e.Audience, &payloadJSON, &e.Timestamp)
		if err == sql.ErrNoRows {
			time.Sleep(2 * time.Second)
			continue
		}
		if err != nil {
			break
		}
		json.Unmarshal(payloadJSON, &e.Payload)
		data, _ := json.Marshal(e)
		fmt.Fprintf(w, "data: %s\n\n", data)
		flusher.Flush()
		lastSeq = e.Sequence
	}
}

