// POST /api/read-operations-state
func ReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator") {
		writeError(w, 403, "forbidden", "Must be dispatcher or admin")
		return
	}

	var req struct {
		Filters map[string]any `json:"filters"`
	}
	mustJSON(r, &req)

	state := models.OperationsState{
		Samples:    []map[string]any{},
		Workers:    []map[string]any{},
		Locations:  []models.OperationsLocation{},
		Connections: []models.OperationsConnection{},
		Routes:     []map[string]any{},
		Handoffs:   []map[string]any{},
		Delays:     []map[string]any{},
		Exceptions: []map[string]any{},
	}

	// Samples
	samplesRows, _ := db.DB.Query(`
		SELECT sample_id, COALESCE(request_id::text,''), status, origin_lat, origin_lng, delivery_deadline::text,
			COALESCE(current_holder_id::text,''), COALESCE(active_journey_id::text,''),
			COALESCE(current_location_lat, 0), COALESCE(current_location_lng, 0),
			COALESCE(location_recorded_at::text, ''), exception
		FROM samples ORDER BY created_at DESC LIMIT 500`)
	if samplesRows != nil {
		defer samplesRows.Close()
		for samplesRows.Next() {
			var id, rid, status, deadline, holder, journey, locAt string
			var oLat, oLng, cLat, cLng float64
			var exc bool
			samplesRows.Scan(&id, &rid, &status, &oLat, &oLng, &deadline, &holder, &journey, &cLat, &cLng, &locAt, &exc)
			stale := true
			if locAt != "" {
				t, err := time.Parse(time.RFC3339, locAt)
				if err == nil {
					stale = time.Since(t) > 15*time.Minute
				}
			}
			entry := map[string]any{
				"sampleId":           id,
				"status":             status,
				"origin":             models.Coordinate{Lat: oLat, Lng: oLng},
				"deliveryDeadline":   deadline,
				"currentHolderId":    holder,
				"activeJourneyId":    journey,
				"latestLocation":     models.Coordinate{Lat: cLat, Lng: cLng},
				"locationRecordedAt": locAt,
				"locationStale":      stale,
			}
			if exc {
				entry["exception"] = true
			}
			state.Samples = append(state.Samples, entry)
		}
	}

	// Workers
	workersRows, _ := db.DB.Query(`SELECT user_id, full_name, roles, active FROM users WHERE active=true`)
	if workersRows != nil {
		defer workersRows.Close()
		for workersRows.Next() {
			var wid, name string
			var rolesJSON []byte
			var active bool
			workersRows.Scan(&wid, &name, &rolesJSON, &active)
			var roles []string
			json.Unmarshal(rolesJSON, &roles)
			var count int
			db.DB.QueryRow(`SELECT COUNT(*) FROM assignments WHERE worker_id=$1`, wid).Scan(&count)

			var wlLat, wlLng float64
			var wlRecAt string
			wlStale := true
			err := db.DB.QueryRow(`SELECT lat, lng, recorded_at::text FROM worker_locations WHERE worker_id=$1`, wid).
				Scan(&wlLat, &wlLng, &wlRecAt)
			if err == nil && wlRecAt != "" {
				t, err := time.Parse(time.RFC3339, wlRecAt)
				if err == nil {
					wlStale = time.Since(t) > 15*time.Minute
				}
			}

			state.Workers = append(state.Workers, map[string]any{
				"workerId":        wid,
				"fullName":        name,
				"roles":           roles,
				"available":       active,
				"status":          "available",
				"capacityUnits":   10,
				"assignmentCount": count,
				"latestLocation":  models.Coordinate{Lat: wlLat, Lng: wlLng},
				"locationStale":   wlStale,
			})
		}
	}

	// Locations
	locRows, _ := db.DB.Query(`SELECT location_id, name, lat, lng, active, functions FROM locations`)
	if locRows != nil {
		defer locRows.Close()
		for locRows.Next() {
			var l models.OperationsLocation
			var lat, lng float64
			var funcJSON []byte
			locRows.Scan(&l.LocationID, &l.Name, &lat, &lng, &l.Active, &funcJSON)
			json.Unmarshal(funcJSON, &l.Functions)
			l.Coordinate = models.Coordinate{Lat: lat, Lng: lng}
			state.Locations = append(state.Locations, l)
		}
	}

	// Connections
	connRows, _ := db.DB.Query(`SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
	if connRows != nil {
		defer connRows.Close()
		for connRows.Next() {
			var c models.OperationsConnection
			connRows.Scan(&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active)
			state.Connections = append(state.Connections, c)
		}
	}

	// Handoffs
	handoffRows, _ := db.DB.Query(`SELECT handoff_id, sample_id, status FROM handoffs LIMIT 200`)
	if handoffRows != nil {
		defer handoffRows.Close()
		for handoffRows.Next() {
			var hid, sid, st string
			handoffRows.Scan(&hid, &sid, &st)
			state.Handoffs = append(state.Handoffs, map[string]any{"handoffId": hid, "sampleId": sid, "status": st})
		}
	}

	// Exceptions
	excRows, _ := db.DB.Query(`SELECT sample_id, exception_reason FROM samples WHERE exception=true LIMIT 200`)
	if excRows != nil {
		defer excRows.Close()
		for excRows.Next() {
			var sid, reason string
			excRows.Scan(&sid, &reason)
			state.Exceptions = append(state.Exceptions, map[string]any{"sampleId": sid, "reason": reason})
		}
	}

	writeJSON(w, 200, map[string]any{"data": state})
}

