// POST /api/report-disruption
func ReportDisruption(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "dispatcher", "administrator", "node_handler") {
		writeError(w, 403, "forbidden", "Must be dispatcher, admin, or node handler")
		return
	}

	var req struct {
