		VALUES ($1, $2, $3, $4, $5, $6)
		ON CONFLICT (worker_id) DO UPDATE SET assignment_id=$2, lat=$3, lng=$4, sequence=$5, recorded_at=$6, stale=false`,
		userID, req.AssignmentID, req.Coordinate.Lat, req.Coordinate.Lng, req.Sequence, req.RecordedAt)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to record location")
		return
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"workerId":     userID,
			"assignmentId": req.AssignmentID,
			"recorded":     true,
		},
	})
}

