	if !requireRole(r, "dispatcher", "administrator") {
		writeError(w, 403, "forbidden", "Must be dispatcher or admin")
		return
	}

	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIds    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	var currentVersion int
	db.DB.QueryRow(`SELECT plan_version FROM journeys WHERE journey_id=$1`, req.TargetJourneyID).Scan(&currentVersion)
	if currentVersion != req.ExpectedPlanVersion {
		writeError(w, 409, "state_snapshot_changed", "Plan version mismatch")
		return
	}

	db.DB.Exec(`UPDATE journeys SET plan_version=plan_version+1, updated_at=NOW() WHERE journey_id=$1`, req.TargetJourneyID)

	// Cancel source journeys, move samples to target
	for _, srcID := range req.SourceJourneyIds {
		var sampleID string
		db.DB.QueryRow(`SELECT sample_id FROM journeys WHERE journey_id=$1`, srcID).Scan(&sampleID)
		db.DB.Exec(`UPDATE samples SET active_journey_id=$1 WHERE sample_id=$2`, req.TargetJourneyID, sampleID)
		db.DB.Exec(`UPDATE journeys SET status='merged', plan_version=plan_version+1 WHERE journey_id=$1`, srcID)
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
