// POST /api/initiate-handoff
func InitiateHandoff(w http.ResponseWriter, r *http.Request) {
	if !hasRole(r, "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator") {
		writeError(w, 403, "forbidden", "Not authorized")
		return
	}

	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	// Verify sender holds the sample
	var holderID string
	db.DB.QueryRow(`SELECT current_holder_id FROM samples WHERE sample_id=$1`, req.SampleID).Scan(&holderID)
	if holderID != currentUserID(r) {
		writeError(w, 403, "forbidden", "You do not hold this sample")
		return
	}

	var handoffID string
	err := db.DB.QueryRow(`
		INSERT INTO handoffs (sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
		VALUES ($1, $2, $3, $4, $5, 'initiated', $6)
		RETURNING handoff_id`,
		req.SampleID, req.FromAssignmentID, req.ToAssignmentID, currentUserID(r), req.ReceiverID, req.InitiatedAt,
	).Scan(&handoffID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to initiate handoff")
		return
	}

	writeJSON(w, 201, map[string]any{
		"data": map[string]any{
			"handoffId": handoffID,
			"status":    "initiated",
		},
	})
}

// POST /api/confirm-handoff
func ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	if !hasRole(r, "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator") {
		writeError(w, 403, "forbidden", "Not authorized")
		return
	}

	var req struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	userID := currentUserID(r)

	var senderID, receiverID, status string
	var senderConfirmed, receiverConfirmed bool
	err := db.DB.QueryRow(`
		SELECT sender_id, receiver_id, status, sender_confirmed, receiver_confirmed FROM handoffs WHERE handoff_id=$1`,
		req.HandoffID).Scan(&senderID, &receiverID, &status, &senderConfirmed, &receiverConfirmed)
	if err == sql.ErrNoRows {
		writeError(w, 404, "not_found", "Handoff not found")
		return
	}
	if err != nil {
		writeError(w, 500, "internal_error", "Database error")
		return
	}

	if req.ConfirmationSide == "sender" && userID != senderID {
		writeError(w, 403, "forbidden", "You are not the sender")
		return
	}
	if req.ConfirmationSide == "receiver" && userID != receiverID {
		writeError(w, 403, "forbidden", "You are not the receiver")
		return
	}

	if req.ConfirmationSide == "sender" {
		if senderConfirmed {
			writeError(w, 409, "concurrent_conflict", "Already confirmed by sender")
			return
		}
		db.DB.Exec(`UPDATE handoffs SET sender_confirmed=true, confirmed_by_sender_at=$1 WHERE handoff_id=$2`, req.ConfirmedAt, req.HandoffID)
	} else {
		if receiverConfirmed {
			writeError(w, 409, "concurrent_conflict", "Already confirmed by receiver")
			return
		}
		db.DB.Exec(`UPDATE handoffs SET receiver_confirmed=true, confirmed_by_receiver_at=$1 WHERE handoff_id=$2`, req.ConfirmedAt, req.HandoffID)
	}

	// Check if both confirmed
	db.DB.QueryRow(`SELECT sender_confirmed, receiver_confirmed FROM handoffs WHERE handoff_id=$1`, req.HandoffID).Scan(&senderConfirmed, &receiverConfirmed)

	if senderConfirmed && receiverConfirmed {
		// Complete the handoff - transfer custody
		var sampleID string
		db.DB.QueryRow(`SELECT sample_id FROM handoffs WHERE handoff_id=$1`, req.HandoffID).Scan(&sampleID)
		db.DB.Exec(`UPDATE samples SET current_holder_id=$1, updated_at=NOW() WHERE sample_id=$2`, receiverID, sampleID)
		db.DB.Exec(`UPDATE handoffs SET status='completed', completed_at=$1 WHERE handoff_id=$2`, req.ConfirmedAt, req.HandoffID)
	}

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"handoffId":        req.HandoffID,
			"confirmationSide": req.ConfirmationSide,
			"confirmed":        true,
		},
	})
}

