	err := db.DB.QueryRow(`
		SELECT sample_id, COALESCE(request_id::text, ''), sample_type_id, status, origin_lat, origin_lng, delivery_deadline::text,
			COALESCE(current_holder_id::text, ''), current_location_lat, current_location_lng, location_recorded_at::text,
			COALESCE(active_journey_id::text, ''), exception, exception_reason, container_type
		FROM samples WHERE sample_id=$1`, sampleID).
		Scan(&s.SampleID, &s.RequestID, &s.SampleTypeID, &s.Status, &originLat, &originLng,
			&s.DeliveryDeadline, &s.CurrentHolderID, &currentLat, &currentLng, &s.LocationRecordedAt,
			&s.ActiveJourneyID, &s.Exception, &s.ExceptionReason, &s.ContainerType)
	if err == sql.ErrNoRows {
		writeError(w, 404, "not_found", "Sample not found")
