import React from 'react';
import { Routes, Route, Navigate, Link } from 'react-router-dom';
import { useAuth } from './auth';
import LoginPage from './pages/LoginPage';
import DashboardPage from './pages/DashboardPage';
import RequestsPage from './pages/RequestsPage';
import NewRequestPage from './pages/NewRequestPage';
import SampleDetailPage from './pages/SampleDetailPage';
import MapPage from './pages/MapPage';
import AdminPage from './pages/AdminPage';

export default function App() {
  const { user, logout } = useAuth();

  if (!user) {
    return (
      <Routes>
        <Route path="/login" element={<LoginPage />} />
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    );
  }

  return (
    <div style={{ display: 'flex', height: '100vh' }}>
      <nav style={{
        width: 220,
        background: '#1a1a2e',
        color: '#eee',
        padding: '1rem',
        display: 'flex',
        flexDirection: 'column',
        gap: '0.5rem',
        flexShrink: 0,
      }}>
        <h3 style={{ margin: 0, fontSize: '1rem', color: '#e94560' }}>Lab Sample System</h3>
        <div style={{ fontSize: '0.8rem', opacity: 0.8 }}>{user.username} ({user.currentRole || user.roles?.[0]})</div>
        <Link to="/" style={{ color: '#eee', textDecoration: 'none' }}>Dashboard</Link>
        <Link to="/requests" style={{ color: '#eee', textDecoration: 'none' }}>Requests</Link>
        <Link to="/map" style={{ color: '#eee', textDecoration: 'none' }}>Map</Link>
        {user.roles?.includes('administrator') && (
          <Link to="/admin" style={{ color: '#eee', textDecoration: 'none' }}>Admin</Link>
        )}
        <div style={{ flex: 1 }} />
        <button onClick={logout} style={{ background: '#e94560', color: '#fff', border: 'none', padding: '0.5rem', borderRadius: 4, cursor: 'pointer' }}>
          Logout
        </button>
      </nav>
      <main style={{ flex: 1, overflow: 'auto', padding: '1.5rem' }}>
        <Routes>
          <Route path="/" element={<DashboardPage />} />
          <Route path="/login" element={<Navigate to="/" replace />} />
          <Route path="/requests" element={<RequestsPage />} />
          <Route path="/requests/new" element={<NewRequestPage />} />
          <Route path="/samples/:sampleId" element={<SampleDetailPage />} />
          <Route path="/map" element={<MapPage />} />
          <Route path="/admin" element={<AdminPage />} />
        </Routes>
      </main>
    </div>
  );
}

