        <div style={{ fontSize: '0.8rem', opacity: 0.8 }}>{user.username} ({user.currentRole || user.roles?.[0]})</div>
        <Link to="/" style={{ color: '#eee', textDecoration: 'none' }}>Dashboard</Link>
        <Link to="/requests" style={{ color: '#eee', textDecoration: 'none' }}>Requests</Link>
