import React, { useState } from 'react';
import { useAuth } from '../auth';

export default function LoginPage() {
  const { login } = useAuth();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(username, password);
    } catch (err: unknown) {
      setError((err as Error).message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh', background: '#0f0f23' }}>
      <form onSubmit={handleSubmit} style={{ background: '#1a1a2e', padding: '2rem', borderRadius: 8, width: 360, color: '#eee' }}>
        <h2 style={{ margin: '0 0 1rem', color: '#e94560' }}>Lab Sample System</h2>
        <h3 style={{ margin: '0 0 1.5rem', fontWeight: 400 }}>Sign In</h3>
        {error && <div style={{ background: '#ff444420', color: '#ff4444', padding: '0.5rem', borderRadius: 4, marginBottom: '1rem' }}>{error}</div>}
        <div style={{ marginBottom: '1rem' }}>
          <label style={{ display: 'block', marginBottom: '0.25rem', fontSize: '0.85rem' }}>Username</label>
          <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} required
            style={{ width: '100%', padding: '0.5rem', borderRadius: 4, border: '1px solid #333', background: '#0f0f23', color: '#eee', boxSizing: 'border-box' }} />
        </div>
        <div style={{ marginBottom: '1.5rem' }}>
          <label style={{ display: 'block', marginBottom: '0.25rem', fontSize: '0.85rem' }}>Password</label>
          <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required
            style={{ width: '100%', padding: '0.5rem', borderRadius: 4, border: '1px solid #333', background: '#0f0f23', color: '#eee', boxSizing: 'border-box' }} />
        </div>
        <button type="submit" disabled={loading}
          style={{ width: '100%', padding: '0.75rem', background: '#e94560', color: '#fff', border: 'none', borderRadius: 4, cursor: 'pointer', fontWeight: 600 }}>
          {loading ? 'Signing in...' : 'Sign In'}
        </button>
      </form>
    </div>
  );
}

