import React, { useEffect, useState } from 'react';
import { useAuth } from '../auth';
import { apiGet } from '../api';
import { Link } from 'react-router-dom';

interface WorkItem {
  workItemId: string;
  type: string;
  sampleId: string;
  status: string;
  deadline?: string;
  fromLocation?: string;
  toLocation?: string;
}

export default function DashboardPage() {
  const { user } = useAuth();
  const [currentWork, setCurrentWork] = useState<WorkItem[]>([]);
  const [pastWork, setPastWork] = useState<WorkItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [tab, setTab] = useState<'current' | 'past'>('current');

  useEffect(() => {
    if (!user) return;
    setLoading(true);
    setError('');
    Promise.all([
      apiGet<{ data: WorkItem[] }>('/work?status=current').catch(() => ({ data: [] })),
      apiGet<{ data: WorkItem[] }>('/work?status=completed').catch(() => ({ data: [] })),
    ])
      .then(([current, past]) => {
        setCurrentWork(current.data || []);
        setPastWork(past.data || []);
      })
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, [user]);

  const items = tab === 'current' ? currentWork : pastWork;

  return (
    <div>
      <h2 style={{ marginTop: 0 }}>Dashboard</h2>
      <div style={{ marginBottom: '1rem', display: 'flex', gap: '0.5rem' }}>
        <button onClick={() => setTab('current')} style={{
          padding: '0.5rem 1rem', border: tab === 'current' ? '2px solid #e94560' : '1px solid #555',
          background: tab === 'current' ? '#e9456020' : 'transparent', color: '#eee', borderRadius: 4, cursor: 'pointer'
        }}>Current ({currentWork.length})</button>
        <button onClick={() => setTab('past')} style={{
          padding: '0.5rem 1rem', border: tab === 'past' ? '2px solid #e94560' : '1px solid #555',
          background: tab === 'past' ? '#e9456020' : 'transparent', color: '#eee', borderRadius: 4, cursor: 'pointer'
        }}>Past ({pastWork.length})</button>
        <Link to="/requests/new" style={{ marginLeft: 'auto', padding: '0.5rem 1rem', background: '#e94560', color: '#fff', textDecoration: 'none', borderRadius: 4 }}>
          New Request
        </Link>
      </div>

      {loading && <p style={{ color: '#888' }}>Loading...</p>}
      {error && <div style={{ color: '#ff4444', marginBottom: '1rem' }}>{error}</div>}

      {!loading && items.length === 0 && (
        <p style={{ color: '#888' }}>No {tab} work items.</p>
      )}

      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
        {items.map((item) => (
          <div key={item.workItemId} style={{
            background: '#1a1a2e', padding: '1rem', borderRadius: 8, border: '1px solid #333',
            display: 'flex', justifyContent: 'space-between', alignItems: 'center'
          }}>
            <div>
              <div style={{ fontWeight: 600 }}>{item.type} — <Link to={`/samples/${item.sampleId}`} style={{ color: '#e94560' }}>{item.sampleId}</Link></div>
              <div style={{ fontSize: '0.85rem', color: '#888' }}>Status: {item.status}</div>
              {item.fromLocation && <div style={{ fontSize: '0.85rem', color: '#888' }}>From: {item.fromLocation} → {item.toLocation}</div>}
              {item.deadline && <div style={{ fontSize: '0.85rem', color: '#888' }}>Deadline: {new Date(item.deadline).toLocaleString()}</div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

