import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { apiGet } from '../api';
import type { Request } from '../types';

export default function RequestsPage() {
  const [requests, setRequests] = useState<Request[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    apiGet<{ data: Request[] }>('/requests')
      .then((res) => setRequests(res.data || []))
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
        <h2 style={{ margin: 0 }}>Requests</h2>
        <Link to="/requests/new" style={{ padding: '0.5rem 1rem', background: '#e94560', color: '#fff', textDecoration: 'none', borderRadius: 4 }}>
          New Request
        </Link>
      </div>

      {loading && <p style={{ color: '#888' }}>Loading...</p>}
      {error && <div style={{ color: '#ff4444', marginBottom: '1rem' }}>{error}</div>}

      {!loading && requests.length === 0 && (
        <p style={{ color: '#888' }}>No requests yet.</p>
      )}

      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
        {requests.map((r) => (
          <div key={r.requestId} style={{
            background: '#1a1a2e', padding: '1rem', borderRadius: 8, border: '1px solid #333'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
              <strong>{r.requestId}</strong>
              <span style={{
                padding: '0.15rem 0.5rem', borderRadius: 4, fontSize: '0.8rem',
                background: r.status === 'completed' ? '#4caf5020' : r.status === 'pending' ? '#ff980020' : '#2196f320',
                color: r.status === 'completed' ? '#4caf50' : r.status === 'pending' ? '#ff9800' : '#2196f3'
              }}>{r.status}</span>
            </div>
            <div style={{ fontSize: '0.85rem', color: '#888' }}>
              Sample: {r.sampleTypeId} | Origin: {r.origin.lat.toFixed(4)}, {r.origin.lng.toFixed(4)}
            </div>
            <div style={{ fontSize: '0.85rem', color: '#888' }}>
              Collection: {new Date(r.collectionWindowStart).toLocaleString()} — {new Date(r.collectionWindowEnd).toLocaleString()}
            </div>
            <div style={{ fontSize: '0.85rem', color: '#888' }}>
              Deadline: {new Date(r.deliveryDeadline).toLocaleString()}
            </div>
            {r.sampleId && (
              <div style={{ marginTop: '0.5rem' }}>
                <Link to={`/samples/${r.sampleId}`} style={{ color: '#e94560', fontSize: '0.85rem' }}>View Sample →</Link>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

