import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { apiGet } from '../api';
import type { Sample } from '../types';

interface SampleLifecycle {
  sampleId: string;
  status: string;
  sample?: Sample;
  history: { action: string; timestamp: string }[];
}

export default function SampleDetailPage() {
  const { sampleId } = useParams<{ sampleId: string }>();
  const [data, setData] = useState<SampleLifecycle | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!sampleId) return;
    apiGet<{ data: SampleLifecycle }>(`/samples/${sampleId}/lifecycle`)
      .then((res) => setData(res.data || null))
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, [sampleId]);

  if (loading) return <p style={{ color: '#888' }}>Loading...</p>;
  if (error) return <div style={{ color: '#ff4444' }}>{error}</div>;
  if (!data) return <div style={{ color: '#888' }}>Sample not found.</div>;

  const s = data.sample;

  return (
    <div>
      <h2 style={{ marginTop: 0 }}>Sample {data.sampleId}</h2>

      {s && (
        <div style={{ background: '#1a1a2e', padding: '1rem', borderRadius: 8, border: '1px solid #333', marginBottom: '1.5rem' }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem', fontSize: '0.9rem' }}>
            <div><strong>Status:</strong> <span style={{ color: '#e94560' }}>{s.status}</span></div>
            <div><strong>Type:</strong> {s.sampleTypeId}</div>
            <div><strong>Origin:</strong> {s.origin.lat.toFixed(4)}, {s.origin.lng.toFixed(4)}</div>
            <div><strong>Deadline:</strong> {new Date(s.deliveryDeadline).toLocaleString()}</div>
            {s.containerType && <div><strong>Container:</strong> {s.containerType}</div>}
            {s.cooled !== undefined && <div><strong>Cooled:</strong> {s.cooled ? 'Yes' : 'No'}</div>}
            {s.currentHolderId && <div><strong>Holder:</strong> {s.currentHolderId}</div>}
            {s.latestLocation && (
              <div>
                <strong>Location:</strong> {s.latestLocation.lat.toFixed(4)}, {s.latestLocation.lng.toFixed(4)}
                {s.locationStale && <span style={{ color: '#ff9800', marginLeft: '0.5rem' }}>(stale)</span>}
              </div>
            )}
            {s.exception && <div style={{ color: '#ff4444' }}><strong>Exception:</strong> {s.exception}</div>}
          </div>
        </div>
      )}

      <h3>Status Timeline</h3>
      {data.history.length === 0 ? (
        <p style={{ color: '#888' }}>No history recorded.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
          {data.history.map((entry, i) => (
            <div key={i} style={{
              display: 'flex', gap: '1rem', padding: '0.5rem', borderLeft: '3px solid #e94560',
              background: '#1a1a2e', borderRadius: '0 4px 4px 0'
            }}>
              <span style={{ color: '#888', minWidth: 180, fontSize: '0.85rem' }}>
                {new Date(entry.timestamp).toLocaleString()}
              </span>
              <span style={{ fontSize: '0.9rem' }}>{entry.action}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

