import React, { useEffect, useRef, useState } from 'react';
import maplibregl from 'maplibre-gl';
import { apiGet } from '../api';

export default function MapPage() {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const [samples, setSamples] = useState<Array<{ sampleId: string; latestLocation?: { lat: number; lng: number }; status: string }>>([]);

  useEffect(() => {
    apiGet<{ data: unknown[] }>('/samples')
      .then((res) => setSamples((res.data || []) as Array<{ sampleId: string; latestLocation?: { lat: number; lng: number }; status: string }>))
      .catch(() => {});
  }, []);

  useEffect(() => {
    if (!mapContainer.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json',
      center: [0, 0],
      zoom: 2,
    });

    map.addControl(new maplibregl.NavigationControl(), 'top-right');
    mapRef.current = map;

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.loaded()) {
      const onLoad = () => {
        addMarkers(map, samples);
      };
      map?.on('load', onLoad);
      return () => { map?.off('load', onLoad); };
    }
    addMarkers(map, samples);
  }, [samples]);

  function addMarkers(map: maplibregl.Map, samples: typeof samples) {
    // Remove existing markers
    const existing = document.querySelectorAll('.maplibregl-marker');
    existing.forEach(el => el.remove());

    samples.forEach((s) => {
      if (!s.latestLocation) return;
      const el = document.createElement('div');
      el.style.width = '12px';
      el.style.height = '12px';
      el.style.borderRadius = '50%';
      el.style.background = s.status === 'exception' ? '#ff4444' : '#e94560';
      el.style.border = '2px solid #fff';

      new maplibregl.Marker({ element: el })
        .setLngLat([s.latestLocation.lng, s.latestLocation.lat])
        .setPopup(new maplibregl.Popup().setText(`Sample ${s.sampleId} (${s.status})`))
        .addTo(map);
    });

    if (samples.length > 0) {
      const bounds = new maplibregl.LngLatBounds();
      samples.forEach((s) => {
        if (s.latestLocation) bounds.extend([s.latestLocation.lng, s.latestLocation.lat]);
      });
      if (!bounds.isEmpty()) map.fitBounds(bounds, { padding: 50 });
    }
  }

  return (
    <div>
      <h2 style={{ marginTop: 0 }}>Live Map</h2>
      <div ref={mapContainer} style={{ width: '100%', height: 'calc(100vh - 120px)', borderRadius: 8, overflow: 'hidden' }} />
    </div>
  );
}

