import React, { useEffect, useState } from 'react';
import { apiGet, apiPost, apiPut, apiDelete } from '../api';

interface User {
  userId: string;
  username: string;
  roles: string[];
}

interface Location {
  locationId: string;
  name: string;
  functions: string[];
  lat: number;
  lng: number;
  active: boolean;
}

export default function AdminPage() {
  const [tab, setTab] = useState<'users' | 'locations' | 'sampleTypes'>('users');
  const [users, setUsers] = useState<User[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [sampleTypes, setSampleTypes] = useState<{ sampleTypeId: string; name: string }[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    const fetcher = tab === 'users' ? apiGet<{ data: User[] }>('/admin/users') :
      tab === 'locations' ? apiGet<{ data: Location[] }>('/admin/locations') :
        apiGet<{ data: { sampleTypeId: string; name: string }[] }>('/admin/sample-types');
    fetcher
      .then((res) => {
        const data = res.data || [];
        if (tab === 'users') setUsers(data as User[]);
        else if (tab === 'locations') setLocations(data as Location[]);
        else setSampleTypes(data as { sampleTypeId: string; name: string }[]);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [tab]);

  return (
    <div>
      <h2 style={{ marginTop: 0 }}>Administration</h2>
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
        {(['users', 'locations', 'sampleTypes'] as const).map((t) => (
          <button key={t} onClick={() => setTab(t)} style={{
            padding: '0.5rem 1rem', border: tab === t ? '2px solid #e94560' : '1px solid #555',
            background: tab === t ? '#e9456020' : 'transparent', color: '#eee', borderRadius: 4, cursor: 'pointer'
          }}>{t}</button>
        ))}
      </div>

      {loading && <p style={{ color: '#888' }}>Loading...</p>}

      {!loading && tab === 'users' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
          {users.map((u) => (
            <div key={u.userId} style={{ background: '#1a1a2e', padding: '1rem', borderRadius: 8, border: '1px solid #333' }}>
              <strong>{u.username}</strong> — {u.roles.join(', ')}
            </div>
          ))}
        </div>
      )}

      {!loading && tab === 'locations' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
          {locations.map((l) => (
            <div key={l.locationId} style={{ background: '#1a1a2e', padding: '1rem', borderRadius: 8, border: '1px solid #333' }}>
              <strong>{l.name}</strong> ({l.locationId})
              <div style={{ fontSize: '0.85rem', color: '#888' }}>
                Functions: {l.functions.join(', ')} | {l.lat.toFixed(4)}, {l.lng.toFixed(4)} | {l.active ? 'Active' : 'Inactive'}
              </div>
            </div>
          ))}
        </div>
      )}

      {!loading && tab === 'sampleTypes' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
          {sampleTypes.map((st) => (
            <div key={st.sampleTypeId} style={{ background: '#1a1a2e', padding: '1rem', borderRadius: 8, border: '1px solid #333' }}>
              <strong>{st.name}</strong> ({st.sampleTypeId})
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

