   460			writeError(w, 500, "internal_error", "Streaming not supported")
   461			return
   462		}
   463	
   464		w.Header().Set("Content-Type", "text/event-stream")
   465		w.Header().Set("Cache-Control", "no-cache")
   466		w.Header().Set("Connection", "keep-alive")
   467		w.Header().Set("Access-Control-Allow-Origin", "*")
   468	
   469		since := r.URL.Query().Get("since")
   470		sinceSeq := int64(0)
   471		if since != "" {
   472			sinceSeq, _ = strconv.ParseInt(since, 10, 64)
   473		}
   474	
   475		// Send existing events since sequence
   476		rows, err := db.DB.Query(`SELECT event_id, sequence, event_type, audience, payload, timestamp::text FROM events WHERE sequence > $1 ORDER BY sequence ASC`, sinceSeq)
   477		if err == nil {
   478			defer rows.Close()
   479			for rows.Next() {
   480				var e models.RealtimeEvent
   481				var payloadJSON []byte
   482				rows.Scan(&e.EventID, &e.Sequence, &e.EventType, &e.Audience, &payloadJSON, &e.Timestamp)
   483				json.Unmarshal(payloadJSON, &e.Payload)
   484				data, _ := json.Marshal(e)
   485				fmt.Fprintf(w, "data: %s\n\n", data)
   486				flusher.Flush()
   487			}
   488		}
   489	
   490		// Keep connection open for new events
   491		lastSeq := sinceSeq
   492		for {
   493			var e models.RealtimeEvent
   494			var payloadJSON []byte
   495			err := db.DB.QueryRow(`SELECT event_id, sequence, event_type, audience, payload, timestamp::text FROM events WHERE sequence > $1 ORDER BY sequence ASC LIMIT 1`, lastSeq).
   496				Scan(&e.EventID, &e.Sequence, &e.EventType, &e.Audience, &payloadJSON, &e.Timestamp)
   497			if err == sql.ErrNoRows {
   498				time.Sleep(2 * time.Second)
   499				continue
   500			}
   501			if err != nil {
   502				break
   503			}
   504			json.Unmarshal(payloadJSON, &e.Payload)
   505			data, _ := json.Marshal(e)
   506			fmt.Fprintf(w, "data: %s\n\n", data)
   507			flusher.Flush()
   508			lastSeq = e.Sequence
   509		}
