   523	func haversine(lat1, lng1, lat2, lng2 float64) float64 {
   524		const R = 6371.0
   525		dLat := (lat2 - lat1) * math.Pi / 180.0
   526		dLng := (lng2 - lng1) * math.Pi / 180.0
   527		a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(lat1*math.Pi/180.0)*math.Cos(lat2*math.Pi/180.0)*math.Sin(dLng/2)*math.Sin(dLng/2)
   528		return R * 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
   529	}
