     9	  const t = token();
    10	  if (t) headers['Authorization'] = `Bearer ${t}`;
    11	
    12	  const res = await fetch(BASE + path, {
    13	    method,
    14	    headers,
    15	    body: body ? JSON.stringify(body) : undefined,
    16	  });
    17	
