import json
with open('contracts/openapi.contract.json') as f:
    c = json.load(f)

# Get key endpoint schemas
for path in ['/api/authenticate-user', '/api/select-active-role', '/api/check-serviceability', '/api/create-collection-request', '/api/list-role-work', '/api/read-sample-lifecycle', '/api/read-operations-state', '/api/read-user/{userId}', '/api/read-ui-bootstrap']:
    print(f'=== {path} ===')
    op = None
    for method in ['post', 'get']:
        if method in c['paths'].get(path, {}):
            op = c['paths'][path][method]
            break
    if op:
        if 'requestBody' in op:
            ref = op['requestBody']['content']['application/json']['schema']
            if '\$ref' in ref:
                ref_name = ref['\$ref'].split('/')[-1]
                print(f'  REQUEST: {json.dumps(c[\"components\"][\"schemas\"][ref_name], indent=2)}')
            else:
                print(f'  REQUEST: {json.dumps(ref, indent=2)}')
        for status in ['200', '201']:
            if status in op['responses']:
                ref = op['responses'][status]['content']['application/json']['schema']
                if '\$ref' in ref:
                    ref_name = ref['\$ref'].split('/')[-1]
                    print(f'  RESPONSE {status}: {json.dumps(c[\"components\"][\"schemas\"][ref_name], indent=2)}')
                else:
                    print(f'  RESPONSE {status}: {json.dumps(ref, indent=2)}')
    print()
" 2>&1

