[?2004lfunc CheckServiceability(w http.ResponseWriter, r *http.Request) {
	if !requireRole(r, "requester", "administrator", "dispatcher") {
		writeError(w, 403, "forbidden", "Must be requester or admin")
		return
	}

	var req struct {
		Origin               models.Coordinate `json:"origin"`
		OriginType           string            `json:"originType"`
		OriginNodeID         string            `json:"originNodeId"`
		SampleTypeID         string            `json:"sampleTypeId"`
		RequestedAt          string            `json:"requestedAt"`
		DeliveryDeadline     string            `json:"deliveryDeadline"`
		EarliestCollectionAt string            `json:"earliestCollectionAt"`
		LatestCollectionAt   string            `json:"latestCollectionAt"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	// Check if a collection point exists within 5km
	serviceable := false
	reason := ""
	if req.OriginType == "node" && req.OriginNodeID != "" {
		var active bool
		var functions []byte
		err := db.DB.QueryRow(`SELECT active, functions FROM locations WHERE location_id = $1`, req.OriginNodeID).
			Scan(&active, &functions)
		if err == sql.ErrNoRows {
			reason = "Origin node not found"
		} else if !active {
			reason = "Origin node is inactive"
		} else {
			var funcs []string
			json.Unmarshal(functions, &funcs)
			hasCollection := false
			for _, f := range funcs {
				if f == "collection_point" {
					hasCollection = true
					break
				}
			}
			if !hasCollection {
				reason = "Origin node is not a collection point"
			} else {
				serviceable = true
			}
		}
	} else {
		// Check for any active collection point within 5km
		rows, err := db.DB.Query(`
			SELECT location_id, lat, lng FROM locations
			WHERE active = true AND functions::text LIKE '%collection_point%'`)
		if err != nil {
			writeError(w, 500, "internal_error", "Database error")
			return
		}
		defer rows.Close()

		for rows.Next() {
			var lid string
			var lat, lng float64
			rows.Scan(&lid, &lat, &lng)
			dist := haversine(req.Origin.Lat, req.Origin.Lng, lat, lng)
			if dist <= 5.0 {
				serviceable = true
				break
			}
		}
		if !serviceable {
			reason = "No active collection point within 5km"
		}
	}

	// Check if a laboratory accepts this sample type
	if serviceable {
		var count int
		db.DB.QueryRow(`
			SELECT COUNT(*) FROM laboratory_acceptance la
			JOIN locations l ON la.laboratory_id = l.location_id
			WHERE la.sample_type_id = $1 AND la.accepts = true AND l.active = true`,
			req.SampleTypeID).Scan(&count)
		if count == 0 {
			serviceable = false
			reason = "No active laboratory accepts this sample type"
		}
	}

	// Serviceability check is a dry run - don't create anything
	writeJSON(w, 200, map[string]any{
		"data": map[string]any{
			"serviceable": serviceable,
			"reason":      reason,
			"checkedAt":   time.Now().UTC().Format(time.RFC3339),
		},
	})
}

